<script setup lang="ts">
import { computed, ref } from 'vue'
import DashboardPageHeader from '@/components/shared/DashboardPageHeader.vue'
import AppButton from '@/components/ui/AppButton.vue'
import TagEditor from '@/components/shared/TagEditor.vue'
import MediaEditor from '@/components/shared/MediaEditor.vue'
import { newId, useWorkspaceStore, normalizeTags, type ManagedPublication } from '@/stores/workspace'
const store = useWorkspaceStore(); const query = ref(''); const draft = ref<ManagedPublication | null>(null); const notice = ref(''); const confirmDelete = ref(false)
const records = computed(() => store.publications.filter(p => `${p.title} ${p.authors} ${p.tags.join(' ')}`.toLowerCase().includes(query.value.toLowerCase())).sort((a,b) => b.year - a.year))
function edit(p: ManagedPublication) { draft.value = JSON.parse(JSON.stringify(p)); notice.value = ''; confirmDelete.value = false }
function create() { draft.value = { id: newId(), title: '', authors: '', venue: '', venueShort: '', year: new Date().getFullYear(), type: 'Conference', tags: [], featured: false, motivation: '', approach: '', abstract: '', paperUrl: '', codeUrl: '', projectUrl: '', bibtex: '', mediaType: 'image', mediaUrl: '', mediaAlt: '', caption: '' }; notice.value = ''; confirmDelete.value = false }
async function save() { if (!draft.value?.title.trim()) { notice.value = 'Please enter a title.'; return }; const value = JSON.parse(JSON.stringify(draft.value)) as ManagedPublication; value.tags = normalizeTags(value.tags); value.image = value.mediaType === 'image' ? value.mediaUrl : ''; const saved = await store.savePublication(value); draft.value = JSON.parse(JSON.stringify(saved)); notice.value = 'Saved. Publications and homepage selected papers use this record.' }
async function remove() { if (!draft.value) return; await store.deletePublication(draft.value); draft.value = null; confirmDelete.value = false; notice.value = 'Publication removed. Its unused media remains in Settings until you delete it.' }
</script>
<template><div><DashboardPageHeader title="Publications" description="Manage your authored papers, figures, methods and publication links."><RouterLink class="dashboard-preview-link" to="/publications">Preview publications ↗</RouterLink><AppButton @click="create">Add publication</AppButton></DashboardPageHeader><p v-if="notice" class="feedback" role="status">{{ notice }}</p><div class="manager-split"><section class="record-list"><input v-model="query" aria-label="Search publications" placeholder="Search publications…" /><button v-for="paper in records" :key="paper.id" class="record-row" :class="{ active: draft?.id === paper.id }" @click="edit(paper)"><strong>{{ paper.title }}</strong><small>{{ paper.year }} · {{ paper.venueShort || paper.type }}{{ paper.featured ? ' · Featured' : '' }}</small><span>{{ paper.tags.join(' · ') }}</span></button><p v-if="!records.length" class="empty-hint">No publications yet.</p></section><section v-if="draft" class="record-editor"><form @submit.prevent="save"><div class="editor-heading"><h2>Publication details</h2><AppButton type="submit">Save publication</AppButton></div><label>Title<input v-model="draft.title" required /></label><label>Authors<input v-model="draft.authors" /></label><div class="field-grid"><label>Venue<input v-model="draft.venue" /></label><label>Venue abbreviation<input v-model="draft.venueShort" /></label><label>Year<input v-model.number="draft.year" type="number" min="1900" max="2200" required /></label><label>Type<select v-model="draft.type"><option>Conference</option><option>Journal</option><option>Preprint</option></select></label></div><label>Motivation · one sentence<textarea v-model="draft.motivation" rows="2" /></label><label>Approach · one sentence<textarea v-model="draft.approach" rows="2" /></label><label>Abstract<textarea v-model="draft.abstract" rows="4" /></label><TagEditor v-model="draft.tags" /><label class="check-field"><input v-model="draft.featured" type="checkbox" /> Show in homepage selected publications</label><MediaEditor :model-value="draft" @update:model-value="value => Object.assign(draft!, value)" /><div class="field-grid"><label>Paper URL<input v-model="draft.paperUrl" type="url" /></label><label>Code URL<input v-model="draft.codeUrl" type="url" /></label><label>Project URL<input v-model="draft.projectUrl" type="url" /></label></div><label>BibTeX<textarea v-model="draft.bibtex" rows="5" /></label><div class="editor-actions"><AppButton type="submit">Save publication</AppButton><button v-if="store.publications.some(p => p.id === draft?.id)" type="button" class="text-action danger" @click="confirmDelete = true">Delete publication</button></div><div v-if="confirmDelete" class="inline-confirm"><span>Delete this publication record?</span><AppButton @click="remove">Delete publication</AppButton><button type="button" @click="confirmDelete = false">Cancel</button></div></form></section><section v-else class="record-editor empty-state"><h2>Your published work</h2><p>Select a publication or add one. Research projects and authored papers remain separate collections.</p></section></div></div></template>
